            </article>
            <article class="h-full p-4 rounded-2xl bg-slate-50 border border-slate-200/80">
                <div class="w-9 h-9 rounded-xl bg-blue-100 text-[#155EAA] flex items-center justify-center mb-3"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19V6l12-3v13M9 19c0 1.1-1.343 2-3 2s-3-.9-3-2 1.343-2 3-2 3 .9 3 2zm12-3c0 1.1-1.343 2-3 2s-3-.9-3-2 1.343-2 3-2 3 .9 3 2zM9 10l12-3"/></svg></div>
